import React from "react";
import axios from "axios";
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import Success from "../../success";
import Form from 'react-bootstrap/Form';
import Button from 'react-bootstrap/esm/Button'
import Logo from '../../assets/images/Logo.jpeg'

const Signup = () => {
  const [signupData, setSignupData] = useState({
    name: "",
    username: "",
    email: "",
    password: "",
  });
    const [signUpSuccess, setSignUpSuccess] = useState(false);
  const navigate = useNavigate();

  const addStudent = () => {
    if (!signupData.name || !signupData.username || !signupData.email || !signupData.password) {
      alert("Please fill in all fields");
      return;
    }
    if (signupData.password.length < 6) {
      alert("Password must be at least 6 characters long");
      return;
    }
    axios
      .post("http://localhost:5000/students/", {
        fullName: signupData.name,
        username: signupData.username,
        email: signupData.email,
        password: signupData.password,
      })
      .then((response) => {
        console.log(response.data);
        // navigate("/dashboard");
            setSignUpSuccess(true);
      })
      .catch((error) => {
        alert("Error adding student:", error);
      });
  };

  if (signUpSuccess) {
    return <Success name={signupData.name} type="Signed up" />;
  }

  return (
    <div className='d-flex justify-content-center align-items-center'>
    <img src={Logo} alt="Logo" className='mt-5 d-block w-25 h-25 border rounded' />
     <div className='m-5 pt-3' style={{width: "450px"}}>
      <h3>Signup</h3>
      <input
        type="text"
        placeholder="Name"
        value={signupData.name}
        onChange={(e) => setSignupData({ ...signupData, name: e.target.value })}
      />
      <input
        type="text"
        placeholder="Username"
        value={signupData.username}
        onChange={(e) =>
          setSignupData({ ...signupData, username: e.target.value })
        }
      />
      <input
        type="email"
        placeholder="Email"
        value={signupData.email}
        onChange={(e) =>
          setSignupData({ ...signupData, email: e.target.value })
        }
      />
      <input
        type="password"
        placeholder="Password"
        value={signupData.password}
        onChange={(e) =>
          setSignupData({ ...signupData, password: e.target.value })
        }
      />
      <button onClick={addStudent}>Sign Up</button>
      <button onClick={() => navigate("/login")}>Go to Login</button>
      <button onClick={() => navigate("/")}>Back to Home</button>
    </div>
    </div>
  );
};

export default Signup;
